// Racer quad: take off and reach the goal point (100, 15, 40) m, about 109 m away, as fast as possible, then stop and
// hold there. The craft's target sensor points at (0, 10, 0); the goal offset is that reading plus a constant.
// Outputs: Motor FL / FR / RL / RR. Controller: the same cascaded PID + quad mixer as drone-hover.json, plus the
// lean limit (how hard it may tilt to accelerate), so 9 genes.
// Reward terms:
//   progress - always-on penalty for distance to the goal (per second, distance / 100)
//   reach    - one-off bonus when first within 3 m of the goal: 2 points per second of episode left (the headline)
//   hold     - seconds within 3 m of the goal after reaching it, slower than 3 m/s
//   upright  - penalty for leaning past 85 deg
//   spin     - penalty for yaw rate
//   crash    - one-off penalty (crash, flipped, or above 60 m)
const GOAL = { x: 100, y: 15, z: 40 };
function terms() { return ["progress", "reach", "hold", "upright", "spin", "crash"]; }

function goalOffset(i) {
  return { dx: i["target.dx"] + GOAL.x, dy: i["target.dy"] + (GOAL.y - 10), dz: i["target.dz"] + GOAL.z };
}

function reward(ctx) {
  const i = ctx.in, s = ctx.state, dt = ctx.dt, m = ctx.memory, g = goalOffset(i);
  const d = Math.sqrt(g.dx * g.dx + g.dy * g.dy + g.dz * g.dz);
  let reach = 0;
  if (d < 3 && !m.reached) { m.reached = true; m.tReach = ctx.t; reach = 2 * (ctx.info.duration - ctx.t); }
  const speed = Math.sqrt(s.vx * s.vx + s.vy * s.vy + s.vz * s.vz);
  const lean = Math.sqrt(i["att.pitch"] * i["att.pitch"] + i["att.roll"] * i["att.roll"]);
  return {
    progress: -d / 100 * dt,
    reach: reach,
    hold: (m.reached && d < 3 && speed < 3) ? dt : 0,
    upright: lean > 85 ? -dt : 0,
    spin: -Math.min(Math.abs(i["rate.yaw"]) / 180, 1) * dt * 0.3,
  };
}

function failed(ctx) {
  const i = ctx.in;
  return ctx.state.crashed || Math.abs(i["att.roll"]) > 120 || i.alt > 60;
}
function terminate(ctx) { return failed(ctx); }

function fitness(ctx) {
  const crash = failed(ctx) ? -2 * (ctx.info.duration - ctx.t) - 1 : 0;
  const s = ctx.sum;
  return { fitness: s.progress + s.reach + s.hold + s.upright + s.spin + crash,
           terms: { crash: crash } };
}

function descriptor(ctx) { return [ctx.memory.tReach || ctx.info.duration, ctx.state.distance]; }

// --- Controller genes (9). Starting values are a timid hover tune: it gets there, slowly, and overshoots.
function genome(base) {
  const g = (name, lo, hi, init) => base.genes.push({ name: name, group: "script", min: lo, max: hi, initial: init, sigma: (hi - lo) / 10 });
  g("hover", 0.05, 0.2, 0.1);
  g("kAlt", 0, 0.1, 0.02);
  g("kVs", 0, 0.1, 0.03);
  g("kAtt", 0, 0.01, 0.003);
  g("kRate", 0, 0.003, 0.0006);
  g("kPos", 0, 5, 0.5);
  g("kVel", 0, 10, 2);
  g("kYaw", 0, 0.006, 0.002);
  g("tiltMax", 10, 80, 45);         // lean limit, deg
  return base;
}

function control(ctx) {
  const G = ctx.genome;
  quad(ctx, {
    hover: G.get("hover"), kAlt: G.get("kAlt"), kVs: G.get("kVs"), kAtt: G.get("kAtt"), kRate: G.get("kRate"),
    kPos: G.get("kPos"), kVel: G.get("kVel"), kYaw: G.get("kYaw"), tiltMax: G.get("tiltMax"),
  }, goalOffset(ctx.in), 0);
}

// --- Quad flight controller (shared by drone-hover / drone-race). Cascade: position -> lean angle -> attitude PD
//     -> motor mixer, plus altitude PD and yaw-rate damping, all in thrust-fraction units (0..1 of static thrust).
//     tgt = offset to the goal (m, world axes); yawSp = yaw-rate setpoint (deg/s).
function quad(ctx, G, tgt, yawSp) {
  const i = ctx.in, m = ctx.memory, dt = ctx.dt;
  const dx = tgt.dx, dy = tgt.dy, dz = tgt.dz;
  // ground velocity from the rate of change of the target offset (there is no velocity sensor), lightly filtered
  const vx = m.pdx === undefined ? 0 : -(dx - m.pdx) / dt, vz = m.pdz === undefined ? 0 : -(dz - m.pdz) / dt;
  m.vx = m.vx === undefined ? 0 : m.vx + (vx - m.vx) * 0.3; m.vz = m.vz === undefined ? 0 : m.vz + (vz - m.vz) * 0.3;
  m.pdx = dx; m.pdz = dz;
  const lim = G.tiltMax;
  const pitchSp = clamp(-(G.kPos * dx - G.kVel * m.vx), -lim, lim);   // nose down to go +x
  const rollSp = clamp(G.kPos * dz - G.kVel * m.vz, -lim, lim);       // roll positive to go +z
  const tilt = Math.min(Math.sqrt(i["att.pitch"] * i["att.pitch"] + i["att.roll"] * i["att.roll"]), 80) * Math.PI / 180;
  const f = (G.hover + G.kAlt * clamp(dy, -10, 10) - G.kVs * i.vs) / Math.max(Math.cos(tilt), 0.3);   // tilt compensation
  const p = G.kAtt * (pitchSp - i["att.pitch"]) - G.kRate * i["rate.pitch"];
  const r = G.kAtt * (rollSp - i["att.roll"]) - G.kRate * i["rate.roll"];
  const y = -G.kYaw * (i["rate.yaw"] - (yawSp || 0));   // speeding up the CW pair (FL, RR) yaws the body to negative rate
  const e = (v) => Math.pow(clamp(v, 0, 1), 1.5);   // thrust fraction -> motor command (static thrust ~ power^2/3)
  ctx.out["Motor FL"] = e(f + p + r + y);
  ctx.out["Motor FR"] = e(f + p - r - y);
  ctx.out["Motor RL"] = e(f - p + r - y);
  ctx.out["Motor RR"] = e(f - p - r + y);
}
